const $=(s,b=document)=>b.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>'S/ '+Number(n||0).toFixed(2);
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',store:'<path d="M3 9h18l-2-5H5L3 9ZM5 9v11h14V9M9 20v-7h6v7"/>',box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4V7ZM3 7l9 4 9-4M12 11v10"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',move:'<path d="M12 3v18M3 12h18m-4-5 5 5-5 5M7 7l-5 5 5 5M7 7l5-5 5 5M7 17l5 5 5-5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M20 12a8 8 0 0 0-.2-2l2-2-2-3-2.5 1A8 8 0 0 0 15 4l-1-2h-4l-1 2a8 8 0 0 0-2.3 2L4 5 2 8l2 2a8 8 0 0 0 0 4l-2 2 2 3 2.7-1A8 8 0 0 0 9 20l1 2h4l1-2a8 8 0 0 0 2.3-2l2.5 1 2-3-2-2a8 8 0 0 0 .2-2Z"/>',external:'<path d="M13 4h7v7M20 4l-9 9M19 14v6H4V5h6"/>',exit:'<path d="M10 17l5-5-5-5M15 12H3M12 3h8v18h-8"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="M12 20h9M17 3a2 2 0 0 1 3 3L9 17l-4 1 1-4L17 3Z"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',alert:'<path d="m12 2 10 19H2L12 2ZM12 9v5m0 3h.01"/>',check:'<path d="m4 12 5 5L20 6"/>',search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>',tag:'<path d="M12 3H4a1 1 0 0 0-1 1v8l9 9 9-9-9-9Z"/><circle cx="7.5" cy="7.5" r="1"/>',monitor:'<rect x="2" y="3" width="20" height="15" rx="2"/><path d="M8 22h8M12 18v4"/>',file:'<path d="M5 3h9l5 5v13H5V3Zm9 0v5h5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',trash:'<path d="M3 6h18M8 6V4h8v2M5 6l1 15h12l1-15M10 10v7M14 10v7"/>'};
const ico=(n,s=19)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.7" fill="none" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.box}</svg>`;
const api=async(url,method='GET',body)=>{const res=await fetch((window.LA_FAVORITA_API_BASE||'')+url,{method,credentials:'include',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await res.json()}catch{data={error:'El servidor devolvió una respuesta inesperada'}}if(!res.ok)throw new Error(data.error||`Error ${res.status}`);return data;};
const app={authenticated:false,configured:true,data:null,tab:'dashboard',branch:'sucursal-1',search:'',modal:null,pendingSections:null,visibleProducts:40,commerce:{rates:{},timeOffers:[],quotes:[]},selectedProducts:new Set()};
const nav=[['dashboard','Resumen','dashboard'],['branches','Sucursales','store'],['products','Productos y precios','box'],['aliases','Nombres alternativos','search'],['campaigns','Campañas','calendar'],['hero','Banners de tienda','monitor'],['themes','Colores por sucursal','settings'],['timeoffers','Ofertas con fecha','tag'],['print','Tarifas de impresión','file'],['quotes','Cotizaciones','file'],['layout','Diseño de página','move'],['settings','Configuración','settings']];
function toast(message,error=false){let el=$('#toast-zone');if(!el){el=document.createElement('div');el.id='toast-zone';document.body.append(el);}el.innerHTML=`<div class="toast" style="${error?'border-color:#f87171;color:#fecaca':''}">${ico(error?'alert':'check',17)} ${esc(message)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.innerHTML='',4200);}
function loginPage(message=''){return `<main class="login-page lf31-login-page"><section class="login-visual"><div class="login-brand"><img src="/assets/logo-favorita-transparente.png" alt="La Favorita"></div><div class="login-headline">Todo tu negocio,<br><em>en un solo lugar.</em></div><p>Productos, stock por sucursal, precios, promociones y cotizaciones.</p><div class="lf31-login-features"><span>${ico('store',16)} Cuatro sucursales</span><span>${ico('box',16)} Control del catálogo</span><span>${ico('calendar',16)} Promociones programadas</span></div></section><section class="login-form-section"><div class="login-box lf31-login-box"><span class="lf31-login-symbol">${ico('store',25)}</span><div class="eyebrow">ACCESO PRIVADO · LA FAVORITA</div><h1>Ingresar al administrador</h1><p>Introduce la contraseña del negocio para acceder al panel.</p><form id="login-form"><div class="form-field"><label for="admin-pass">Contraseña</label><div class="lf31-pass-field"><input id="admin-pass" name="password" type="password" autocomplete="current-password" required placeholder="Escribe tu contraseña"><button data-action="toggle-password" type="button" class="lf31-show-pass" aria-controls="admin-pass" aria-pressed="false" aria-label="Mostrar contraseña">Mostrar</button></div><small class="lf31-login-tip">Puedes mostrar las letras para comprobar que escribiste bien.</small></div><button class="btn btn-primary lf31-login-submit" type="submit">Entrar al panel ${ico('arrow',17)}</button>${message?`<div class="login-error" role="alert">${esc(message)}</div>`:''}</form><div class="lf31-login-bottom">${ico('alert',15)} Área exclusiva para personal autorizado</div></div></section></main>`;}
function render(){if(!app.authenticated){$('#admin-app').innerHTML=loginPage();return;}const d=app.data;const current=nav.find(n=>n[0]===app.tab)||nav[0];$('#admin-app').innerHTML=`<aside class="sidebar"><a href="/" class="logo-panel" target="_blank"><img src="/assets/logo-favorita-transparente.png" alt="La Favorita"></a><div class="side-label">Panel de control</div><nav class="side-nav">${nav.map(([id,label,ic])=>`<button class="side-link ${app.tab===id?'active':''}" data-tab="${id}">${ico(ic)} ${label}</button>`).join('')}</nav><div class="side-spacer"></div><div class="side-bottom"><a href="/" target="_blank">${ico('external',17)} Ver tienda pública</a><button data-action="logout">${ico('exit',17)} Cerrar sesión</button></div></aside><div class="admin-main"><header class="topbar"><div class="bread">Administración / <strong>${current[1]}</strong></div><div class="top-actions"><span class="live-pill"><span class="live-dot"></span> API conectada</span><span class="avatar">LF</span></div></header><nav class="mobile-admin-top">${nav.map(([id,label,ic])=>`<button class="side-link ${app.tab===id?'active':''}" data-tab="${id}">${ico(ic,15)} ${label}</button>`).join('')}</nav><main class="content">${content()}</main></div><div id="modal-zone"></div>`;}
function title(title,desc,action=''){return `<div class="page-title"><div><div class="eyebrow">LA FAVORITA · GESTIÓN</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function content(){switch(app.tab){case 'dashboard':return dashboard();case 'branches':return branchPage();case 'products':return productsPage();case 'aliases':return aliasesPage();case 'campaigns':return campaignPage();case 'hero':return heroPage();case 'themes':return themesPage();case 'layout':return layoutPage();case 'settings':return settingsPage();case 'timeoffers':return timeOffersPage();case 'print':return printRatesPage();case 'quotes':return quotesPage();default:return dashboard();}}
function aliasesPage(){
 const names=(app.data.lexicon||[]).slice().sort((a,b)=>a.aliasText.localeCompare(b.aliasText,'es'));
 return `${title('Nombres alternativos','Ayuda al cotizador a entender cómo piden los útiles en la tienda. Las expresiones dudosas requieren revisión.')}
 <div class="two-cols"><section class="panel"><div class="panel-header"><h2>Agregar una expresión</h2></div>
 <form id="alias-form">
   <div class="form-field"><label>Cómo lo escribe el cliente</label><input name="aliasText" maxlength="120" required placeholder="Ej.: lapisero"></div>
   <div class="form-field"><label>Nombre del catálogo</label><input name="canonicalTerm" maxlength="120" required placeholder="Ej.: lapicero"></div>
   <div class="form-field"><label>Estado</label><select name="status"><option value="review">Pendiente de revisar</option><option value="approved">Equivalencia comprobada</option></select></div>
   <div class="form-field"><label>Nota (opcional)</label><input name="note" maxlength="250" placeholder="Aclaración para el equipo"></div>
   <button type="submit" class="btn btn-primary">${ico('plus',16)} Guardar nombre alternativo</button>
 </form></section>
 <section class="panel"><div class="panel-header"><h2>Expresiones registradas (${names.length})</h2></div>
 ${names.map(a=>`<div class="status-card"><div><strong>${esc(a.aliasText)} → ${esc(a.canonicalTerm)}</strong>
 <small>${a.status==='approved'?'Comprobado · Se aplica al cotizar':'Pendiente · No se sustituye automáticamente'}</small></div>
 <button class="btn btn-small btn-danger" data-action="delete-alias" data-key="${esc(a.aliasKey)}" title="Eliminar equivalencia">${ico('trash',15)}</button></div>`).join('')}
 </section></div>`;
}
function selectedBranch(){return app.data.branches.find(b=>b.id===app.branch)||app.data.branches[0];}
function countOffer(b){return app.data.offers.filter(o=>o.branchId===b.id);}
function dashboard(){const d=app.data;const cur=selectedBranch();const offers=countOffer(cur);const low=offers.filter(o=>o.stock>0&&o.stock<=o.minStock).length;return `${title('Tu negocio, de un vistazo.','Controla tu catálogo, tus cuatro sucursales y las novedades de la web.',`<a class="btn btn-primary" target="_blank" href="/">${ico('external',16)} Abrir web pública</a>`)}<div class="stat-grid"><div class="stat-card"><div class="stat-icon">${ico('store',22)}</div><strong>${d.branches.length}</strong><span>Sucursales configuradas</span></div><div class="stat-card"><div class="stat-icon">${ico('box',22)}</div><strong>${d.products.length}</strong><span>Productos registrados</span></div><div class="stat-card"><div class="stat-icon">${ico('calendar',22)}</div><strong>${d.campaigns.filter(c=>c.enabled).length}</strong><span>Campañas habilitadas</span></div><div class="stat-card"><div class="stat-icon">${ico('alert',22)}</div><strong>${low}</strong><span>Stock bajo en ${esc(cur.name)}</span></div></div><div class="two-cols"><div class="panel"><div class="panel-header"><h2>Estado de las sucursales</h2><button class="btn-link" data-tab="branches">Configurar ${ico('arrow',14)}</button></div>${d.branches.map(b=>`<div class="status-card"><div><span class="status-dot" style="background:${b.active?'#75dfaa':'#f68f91'}"></span><strong>${esc(b.name)}</strong><small>${esc(b.subtitle)}</small></div><span class="muted tiny">${countOffer(b).length} artículos</span></div>`).join('')}</div><div class="panel"><div class="panel-header"><h2>Accesos rápidos</h2></div><p class="panel-intro">Los cambios que guardes se reflejan en la web pública sin modificar archivos ni volver a desplegarla.</p><div class="quick-actions"><button class="quick-action" data-action="new-product">${ico('plus',18)} Nuevo producto</button><button class="quick-action" data-action="new-campaign">${ico('calendar',18)} Nueva campaña</button><button class="quick-action" data-tab="layout">${ico('move',18)} Mover secciones</button><button class="quick-action" data-tab="settings">${ico('settings',18)} Aspecto del sitio</button><button class="quick-action" data-action="export-backup">${ico('file',18)} Descargar respaldo</button></div></div></div>`;}
function branchPage(){return `${title('Tus sucursales.','Configura la información que los visitantes ven antes y después de elegir su tienda.',`<button class="btn btn-primary" data-action="new-branch">${ico('plus',16)} Nueva sucursal</button>`)}<div class="branch-edit-grid">${app.data.branches.map((b,i)=>`<article class="branch-edit-card" style="--accent:${esc(app.commerce.branchCardStyles?.[b.id]?.borderColor||b.accent)}"><div class="accent-tag">PUNTO DE ATENCIÓN ${String(i+1).padStart(2,'0')}</div><h3>${esc(b.name)}</h3><p>${esc(b.subtitle)}</p><p>${esc(b.address)}</p><div style="display:flex;align-items:center;justify-content:space-between;margin-top:28px"><span class="${b.active?'on-pill':'off-pill'}">${b.active?'Visible en web':'Oculta'}</span><button class="btn btn-secondary btn-small" data-action="edit-branch" data-id="${esc(b.id)}">${ico('edit',15)} Editar sucursal</button></div><div class="branch-v10-actions"><button class="btn btn-secondary btn-small" type="button" data-action="toggle-branch" data-id="${esc(b.id)}">${b.active?'Quitar tarjeta de portada':'Volver a mostrar tarjeta'}</button></div></article>`).join('')}</div>`;}
function offerFor(branchId,productId){return app.data.offers.find(o=>o.branchId===branchId&&o.productId===productId)||{price:0,stock:0};}
function productsPage(){const d=app.data;const b=selectedBranch();const q=app.search.toLocaleLowerCase();const products=d.products.filter(p=>!q||[p.name,p.brand,p.sku,p.searchAliases].some(t=>String(t).toLocaleLowerCase().includes(q)));return `${title('Productos y precios.','Edita nombres, presentaciones, fotografías, precios y stock. Cada sucursal es independiente.',`<button class="btn btn-primary" data-action="new-product">${ico('plus',17)} Agregar producto</button>`)}<div class="toolbar"><input class="text-search" id="product-search" type="search" value="${esc(app.search)}" placeholder="Buscar producto, marca o SKU..."><select id="admin-branch" class="branch-select" aria-label="Sucursal a consultar">${d.branches.map(v=>`<option value="${esc(v.id)}" ${v.id===app.branch?'selected':''}>${esc(v.name)}</option>`).join('')}</select><span class="muted tiny">${products.length} resultados</span></div><div class="bulk-actions"><label class="bulk-select-all"><input type="checkbox" id="bulk-select-filtered" ${products.length>0&&products.every(p=>app.selectedProducts.has(p.id))?'checked':''}> Seleccionar los ${products.length} resultados filtrados</label><strong id="bulk-selected-count">${app.selectedProducts.size} seleccionados</strong><button type="button" class="btn btn-small btn-primary" data-action="bulk-publish" ${app.selectedProducts.size?'':'disabled'}>Publicar en ${esc(b.name)}</button><button type="button" class="btn btn-small btn-secondary" data-action="bulk-hide" ${app.selectedProducts.size?'':'disabled'}>Ocultar en ${esc(b.name)}</button><button type="button" class="btn btn-small btn-secondary" data-action="bulk-clear">Limpiar selección</button></div><div class="table-wrap"><table><thead><tr><th>Seleccionar</th><th>Producto</th><th>Marca</th><th>Tipo / Presentación</th><th>Precio · ${esc(b.name)}</th><th>Stock</th><th>Acción</th></tr></thead><tbody id="products-body">${productRows(products.slice(0,app.visibleProducts))}</tbody></table></div>${products.length>app.visibleProducts?`<button class="btn btn-secondary" style="margin-top:15px" data-action="more-admin-products">Ver más productos (${products.length-app.visibleProducts} pendientes)</button>`:''}`;}
function productRows(list){return list.map(p=>{const o=offerFor(app.branch,p.id);const klass=o.stock===0?'out':o.stock<=o.minStock?'low':'';return `<tr><td><input class="bulk-product-check" type="checkbox" data-product="${esc(p.id)}" aria-label="Seleccionar ${esc(p.name)}" ${app.selectedProducts.has(p.id)?'checked':''}></td><td><div class="table-product"><div class="table-thumb">${p.imageUrl?`<img src="${esc(p.imageUrl)}" loading="lazy" alt="">`:ico('box',18)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.sku)}${!p.active?' · Oculto':''}${!o.active?' · Precio y stock sin publicar':''}</small></div></div></td><td>${esc(p.brand)}</td><td>${p.isService?'Servicio':esc(p.unitLabel)+(p.unitsPerPack>1?' x'+p.unitsPerPack:'')}</td><td class="strong">${cash(o.price)}${!o.active?'<br><small>Por confirmar</small>':''}</td><td>${p.isService?'<span class="muted tiny">No usa stock</span>':`<span class="stock-badge ${klass}">${o.stock} unidades</span>`}</td><td><button class="btn btn-small btn-secondary" data-action="edit-product" data-id="${esc(p.id)}">${ico('edit',15)} Editar</button> <button class="btn btn-small btn-secondary" data-action="toggle-product" data-id="${esc(p.id)}">${p.active?'Ocultar':'Reactivar'}</button></td></tr>`;}).join('');}
function heroPage(){
 const b=selectedBranch(),list=app.commerce.heroSlides?.[b.id]||[],interval=app.commerce.heroIntervals?.[b.id]||6;
 const preview=record=>`<article class="lf31-hero-row"><img src="${esc(record.imageUrl)}" alt="" loading="lazy"><div><strong>${esc(record.title)}</strong><small>${esc(record.eyebrow||'')} · ${record.enabled===false?'Oculto':'Visible'}</small></div><div class="lf31-hero-actions"><button type="button" data-action="hero-up" data-id="${esc(record.id)}" class="btn btn-small btn-secondary" aria-label="Subir banner">↑</button><button type="button" data-action="hero-down" data-id="${esc(record.id)}" class="btn btn-small btn-secondary" aria-label="Bajar banner">↓</button><button data-action="edit-hero" data-id="${esc(record.id)}" class="btn btn-small btn-secondary">Editar</button><button data-action="delete-hero" data-id="${esc(record.id)}" class="btn btn-small btn-danger">Quitar</button></div></article>`;
 return `${title('Banners de Mi tienda','Controla qué aparece en el carrusel comercial de cada sucursal. No modifica el carrusel de la portada.',`<button class="btn btn-primary" data-action="new-hero">${ico('plus',17)} Nuevo banner</button>`)}<div class="panel lf31-manager"><div class="toolbar"><label for="commerce-branch">Sucursal</label><select id="commerce-branch" class="branch-select">${app.data.branches.map(x=>`<option value="${esc(x.id)}" ${b.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><form id="hero-interval-form" class="lf31-timing"><label for="hero-interval">Cambiar banner automáticamente cada</label><input id="hero-interval" type="number" name="seconds" value="${esc(interval)}" min="3" max="30" required> <span>segundos</span><button class="btn btn-primary btn-small" type="submit">Guardar tiempo</button></form><p class="muted tiny">Los cambios de esta sección afectan únicamente a ${esc(b.name)}. Puedes usar imágenes PNG con transparencia para que sobresalgan del banner.</p><div class="lf31-hero-list">${list.length?list.map(preview).join(''):'<p class="muted">No hay fichas: crea un banner nuevo.</p>'}</div><a class="btn btn-secondary" target="_blank" href="/tienda/${esc(b.id)}">Ver carrusel en la web ${ico('external',15)}</a></div>`;
}
function themesPage(){
 const b=selectedBranch(),t=app.commerce.branchThemes?.[b.id]||{};
 const fields=[['bg','Fondo principal'],['surface','Paneles y tarjetas'],['surface2','Superficie secundaria'],['surface3','Bloques destacados'],['pink','Color principal de botones'],['teal','Color de contraste'],['lav','Acento adicional'],['accentPink','Color publicitario'],['accentTeal','Color secundario de marca']];
 return `${title('Colores por sucursal','Cada tienda puede tener un ambiente visual diferente. Cambia colores sin modificar productos ni promociones.')}<div class="panel lf31-manager"><div class="toolbar"><label for="commerce-branch">Sucursal</label><select id="commerce-branch" class="branch-select">${app.data.branches.map(x=>`<option value="${esc(x.id)}" ${b.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="lf31-theme-preview" style="background:${esc(t.bg||'#14273b')};border-color:${esc(t.teal||'#4cdeed')}"><strong style="color:${esc(t.pink||'#ff51af')}">${esc(b.name)}</strong><span style="background:${esc(t.surface||'#152e45')};color:#fff">Vista de tus paneles</span><span style="background:${esc(t.teal||'#4cdeed')};color:#0c1830">Contraste</span></div><form id="branch-theme-form"><div class="lf31-theme-grid">${fields.map(([key,title])=>`<label class="lf31-color-field"><span>${title}</span><input type="color" name="${key}" value="${esc(t[key]||'#305071')}" required><small>${esc(t[key]||'')}</small></label>`).join('')}</div><button type="submit" class="btn btn-primary">Guardar colores de ${esc(b.name)}</button></form><p class="muted tiny">Los cambios se aplicarán al entrar en esta sucursal y al cambiar de tienda. La portada general mantiene su diseño.</p></div>`;
}
function campaignPage(){const d=app.data;return `${title('Campañas y promociones.','Activa temporadas por fecha, define su mensaje y elige las sucursales donde aparecerán.',`<button class="btn btn-primary" data-action="new-campaign">${ico('plus',17)} Nueva campaña</button>`)}<div class="campaign-grid">${d.campaigns.slice().sort((a,b)=>a.priority-b.priority).map(c=>`<article class="campaign-card" style="--accent:${esc(c.accent)}"><div class="campaign-art"><img class="admin-campaign-preview" src="${esc(c.imageUrl||({navidad:'/assets/editorial/navidad-decoracion-v30.png',escolar:'/assets/editorial/mochila-escolar-v30.png',destacados:'/assets/editorial/resaltadores-v30.png'}[c.background]||'/assets/editorial/mochila-escolar-v30.png'))}" alt=""><span class="campaign-kicker">${esc(c.eyebrow)}</span><h3>${esc(c.title)}</h3></div><div class="campaign-body"><div><p>${esc(c.startDay)} → ${esc(c.endDay)} · ${c.branches.includes('all')?'4 sucursales':c.branches.length+' sucursal(es)'}</p><span class="${c.enabled?'on-pill':'off-pill'}">${c.enabled?'Habilitada':'Pausada'}</span></div><button class="btn btn-small btn-secondary" data-action="edit-campaign" data-id="${esc(c.id)}">${ico('edit',15)} Editar</button></div></article>`).join('')}</div>`;}
function layoutList(){return `<div class="drag-list" id="layout-list">${app.pendingSections.map((s,i)=>`<div class="drag-row" draggable="true" data-drag-id="${esc(s.id)}"><span class="drag-handle" title="Arrastra para ordenar">⠿</span><span class="drag-name">${i+1}. ${esc(s.title)}</span><label class="tiny muted" for="section-${esc(s.id)}">Mostrar</label><input class="toggle" type="checkbox" id="section-${esc(s.id)}" data-section-toggle="${esc(s.id)}" ${s.enabled?'checked':''}></div>`).join('')}</div>`;}
function layoutPage(){if(!app.pendingSections)app.pendingSections=structuredClone(app.data.sections).sort((a,b)=>a.order-b.order);return `${title('Diseña la página a tu manera.','Arrastra las secciones para cambiar su orden o desactívalas. Se aplica a las cuatro sucursales.',`<a target="_blank" href="/tienda/${esc(app.branch)}" class="btn btn-secondary">${ico('external',16)} Ver resultado</a>`)}<div class="panel" style="max-width:860px"><p class="layout-guide">Mantén pulsada la barra ⠿ de una fila y arrástrala a otra posición. Puedes ocultar una sección con el interruptor. La cabecera y la campaña principal siempre estarán arriba.</p>${layoutList()}<div style="margin-top:23px;display:flex;justify-content:flex-end"><button class="btn btn-primary" data-action="save-layout">${ico('check',16)} Publicar nuevo orden</button></div></div>`;}
function input(label,name,value='',type='text',hint='',attrs=''){return `<div class="form-field"><label for="f-${name}">${label}</label><input id="f-${name}" type="${type}" name="${name}" value="${esc(value)}" ${attrs}>${hint?`<div class="form-hint">${hint}</div>`:''}</div>`;}
function textarea(label,name,value=''){return `<div class="form-field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;}
function check(label,name,checked=false){return `<label style="display:flex;gap:9px;align-items:center;font-size:12px;color:#d6dcea;margin:5px 0 16px"><input type="checkbox" name="${name}" ${checked?'checked':''} style="accent-color:var(--pink)"> ${label}</label>`;}
function timeOffersPage(){
 const active=app.commerce.timeOffers||[],branch=selectedBranch();const products=app.data.products.filter(p=>p.active&&app.data.offers.some(o=>o.branchId===branch.id&&o.productId===p.id&&o.active&&o.price>0));
 const rows=active.filter(o=>o.branchId===branch.id).map(o=>{const p=app.data.products.find(p=>p.id===o.productId);const now=Date.now(),start=Date.parse(o.startAt),end=Date.parse(o.endAt),status=now<start?'Programada':now<end?'Activa':'Terminada';return `<tr><td><strong>${esc(p?.name||o.productId)}</strong><small>${esc(p?.sku||'')}</small></td><td>${cash(o.salePrice)}</td><td>${esc(new Date(o.startAt).toLocaleString('es-PE'))}</td><td>${esc(new Date(o.endAt).toLocaleString('es-PE'))}</td><td>${status}</td><td><button class="btn btn-small btn-danger" data-action="disable-timeoffer" data-product="${esc(o.productId)}" data-branch="${esc(branch.id)}">Finalizar</button></td></tr>`;}).join('');
 return `${title('Ofertas programadas','Descuentos por sucursal que se activan y vencen automáticamente. El precio normal permanece guardado.')}<div class="panel" style="margin-bottom:20px"><div class="form-field"><label>Sucursal</label><select class="branch-select" id="commerce-branch">${app.data.branches.map(b=>`<option value="${esc(b.id)}" ${b.id===branch.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><form id="timeoffer-form"><div class="form-field"><label>Producto que tendrá descuento</label><select name="productId" required class="branch-select" style="width:100%;max-width:100%">${products.map(p=>`<option value="${esc(p.id)}">${esc(p.sku)} — ${esc(p.name)} (${cash(app.data.offers.find(o=>o.branchId===branch.id&&o.productId===p.id)?.price)})</option>`).join('')}</select></div><div class="form-grid">${input('Precio promocional S/','salePrice','','number','','min="0.01" step="0.01" required')}${input('Inicio de la oferta','startAt','','datetime-local','','required')}${input('Fin de la oferta','endAt','','datetime-local','','required')}</div><button class="btn btn-primary" type="submit">${ico('check',16)} Programar oferta</button></form></div><div class="panel"><h2>Ofertas de esta sucursal</h2><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Oferta</th><th>Inicio</th><th>Fin</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Sin ofertas programadas.</td></tr>'}</tbody></table></div></div>`;
}
function printRatesPage(){const branch=selectedBranch(),rates=app.commerce.rates?.[branch.id]||{};return `${title('Tarifas de copias, impresiones y escaneos','La calculadora usa estos valores de la sucursal. Las tarifas se guardan en el servidor.')}<div class="panel"><div class="form-field"><label>Sucursal</label><select class="branch-select" id="commerce-branch">${app.data.branches.map(b=>`<option value="${esc(b.id)}" ${b.id===branch.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><form id="print-rates-form"><div class="form-grid">${input('Fotocopia B/N por cara (S/)','copyBW',rates.copyBW??.15,'number','','min="0" step="0.01" required')}${input('Impresión B/N por cara (S/)','printBW',rates.printBW??.20,'number','','min="0" step="0.01" required')}${input('Escaneo por página (S/)','scanPage',rates.scanPage??0,'number','','min="0" step="0.01" required')}${input('Fotocopia a color, tarifa base (S/)','copyColor',rates.copyColor??0,'number','','min="0" step="0.01" required')}${input('Impresión a color, tarifa base (S/)','printColor',rates.printColor??0,'number','','min="0" step="0.01" required')}${input('Desde cuántas caras aplicar descuento','bulkAfter',rates.bulkAfter??100,'number','','min="1" required')}${input('Descuento por volumen (%)','bulkDiscount',rates.bulkDiscount??0,'number','','min="0" max="90" step="0.1"')}${input('Descuento por doble cara (%)','duplexDiscount',rates.duplexDiscount??0,'number','','min="0" max="90" step="0.1"')}${input('Factor poco color','coverageLow',rates.coverageLow??.2,'number','','min="0.01" step="0.01"')}${input('Factor mucho color','coverageHigh',rates.coverageHigh??.7,'number','','min="0.01" step="0.01"')}${input('Precio mínimo a color (S/)','minColor',rates.minColor??0,'number','','min="0" step="0.01"')}${input('Precio máximo a color (S/)','maxColor',rates.maxColor??0,'number','','min="0" step="0.01"')}</div><p class="muted">El cálculo de cobertura es una estimación por categoría seleccionada por el cliente. Una futura detección automática de color requerirá analizar archivos con un motor dedicado.</p><button type="submit" class="btn btn-primary">${ico('check',16)} Guardar tarifas</button></form></div>`;}
function quotesPage(){const entries=(app.commerce.quotes||[]).filter(q=>!app.search||[q.code,q.branchId,q.inputText].some(x=>String(x||'').toLowerCase().includes(app.search.toLowerCase())));return `${title('Historial de cotizaciones','Consulta el código del cliente para revisar exactamente los productos, cantidades y precios calculados.')}<div class="toolbar"><input id="quote-admin-search" class="text-search" placeholder="Buscar código LF-000001 o sucursal" value="${esc(app.search)}"></div><div class="quote-admin-list">${entries.map(q=>`<details class="panel" style="margin-bottom:12px"><summary style="cursor:pointer;display:flex;gap:20px;align-items:center;justify-content:space-between"><strong>${esc(q.code)}</strong><span>${esc(app.data.branches.find(b=>b.id===q.branchId)?.name||q.branchId)}</span><span>${new Date(q.createdAt).toLocaleString('es-PE')}</span><strong>${cash(q.result?.total)}</strong></summary><div style="padding-top:15px"><p>Modalidad: ${esc(q.tier)} · ${esc(q.inputType)} · Artículos incluidos: ${q.result?.includedCount??0}</p><div class="table-wrap"><table><thead><tr><th>Código</th><th>Producto</th><th>Marca</th><th>Cant.</th><th>P. unitario</th><th>Subtotal</th></tr></thead><tbody>${(q.lines||[]).map(x=>`<tr><td>${esc(x.sku)}</td><td>${esc(x.name)}</td><td>${esc(x.brand)}</td><td>${x.quantity}</td><td>${cash(x.unitPrice)}</td><td>${cash(x.lineTotal)}</td></tr>`).join('')}</tbody></table></div>${q.result?.missing?.length?`<p>No incluidos: ${esc(q.result.missing.join('; '))}</p>`:''}</div></details>`).join('')||'<div class="panel">Todavía no hay cotizaciones guardadas.</div>'}</div>`;}
async function reloadCommerce(){app.commerce=await api('/api/admin/commerce');}
function settingsPage(){const s=app.data.settings;return `${title('Configuración general.','Modifica textos, colores y la comunicación visual de la tienda sin editar archivos.')}<div class="panel settings-panel"><form id="settings-form"><div class="form-grid">${input('Nombre del negocio','businessName',s.businessName)}${input('Lema de la marca','tagline',s.tagline)}</div>${input('Frase de anuncio superior','announcement',s.announcement)}${input('Titular inicial','heroHeadline',s.heroHeadline,'text','Separa dos líneas con |, por ejemplo: CADA IDEA|CUENTA.')}${textarea('Descripción de portada','heroDescription',s.heroDescription)}<div class="form-divider"></div><div class="form-subtitle">Colores principales</div><div class="form-grid">${input('Color magenta','primaryColor',s.primaryColor,'color')}${input('Color turquesa','secondaryColor',s.secondaryColor,'color')}</div><div class="settings-actions"><button type="submit" class="btn btn-primary">${ico('check',17)} Guardar configuración</button></div></form></div>`;}
function modalShell(label,content,formId='',submit='Guardar cambios'){return `<div class="backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(label)}"><div class="modal-header"><h2>${esc(label)}</h2><button type="button" class="modal-close" data-action="close-modal">${ico('close',19)}</button></div><div class="modal-body">${content}</div><div class="modal-footer"><button class="btn btn-secondary" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit" form="${formId}">${ico('check',16)} ${esc(submit)}</button></div></div></div>`;}
